import{d as g,C as o,o as h,c as d,j as i,a,E as e,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"中庸·第30章","description":"《中庸》第 30 章——仲尼祖述尧舜，宪章文武；上律天时，下袭水土；万物并育而不相害，道并行而不相悖，小德川流，大德敦化。","frontmatter":{"title":"中庸·第30章","description":"《中庸》第 30 章——仲尼祖述尧舜，宪章文武；上律天时，下袭水土；万物并育而不相害，道并行而不相悖，小德川流，大德敦化。","category":"guide","aliases":["第30章","中庸第30章","祖述尧舜"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-30.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-30.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-30.md"},b=g({...m,setup(p){const r=[{id:"zushu",label:"仲尼祖述尧舜 · 宪章文武 · 上律天时，下袭水土",showLabel:!0,sentences:[["仲尼",{text:"祖述",glossary:"zushu"},"尧舜，",{text:"宪章",glossary:"xianzhang"},"文武；上",{text:"律天时",glossary:"lvtianshi"},"，下",{text:"袭水土",glossary:"xishuitu"},"。"]],note:"「仲尼祖述尧舜，宪章文武」——孔子远宗尧舜之道（祖述＝宗奉而传述），取法文王、武王之制（宪章＝取法其典章）；「上律天时，下袭水土」——上则顺应天时，下则因循水土。四句写孔子之学的渊源与法度。"},{id:"piru",label:"辟如天地之无不持载 · 四时错行，日月代明",showLabel:!0,sentences:[["辟如天地之无不",{text:"持载",glossary:"chizai"},"，无不",{text:"覆帱",glossary:"fudao"},"，辟如四时之",{text:"错行",glossary:"cuoxing"},"，如日月之",{text:"代明",glossary:"daiming"},"。"]],note:"「辟如天地之无不持载，无不覆帱」——好比天地，无不承载、无不覆盖；「辟如四时之错行，如日月之代明」——好比四季交替运行、日月轮流照明。以天地、四时、日月喻孔子之德的广大与恒常。"},{id:"chuandun",label:"万物并育而不相害 · 小德川流，大德敦化",showLabel:!0,sentences:[["万物并育而不相害，道并行而不相悖，",{text:"小德川流",glossary:"xiaodechuanliu"},"，",{text:"大德敦化",glossary:"dadedunhua"},"，此天地之所以为大也。"]],note:"「万物并育而不相害，道并行而不相悖」——万物一同生长而不相妨害，众道并行而不相冲突；「小德川流，大德敦化」——小德如川流各自奔流，大德则敦厚而化育万物；「此天地之所以为大也」。此章以「川流／敦化」为全篇名段。"}],s=[{id:"zushu",term:"祖述",pinyin:"zǔ shù",meaning:"朱注：「祖述者，远宗其道。」"},{id:"xianzhang",term:"宪章",pinyin:"xiàn zhāng",meaning:"朱注：「宪章者，近守其法。」"},{id:"lvtianshi",term:"上律天时",pinyin:"shàng lǜ tiān shí",meaning:"律：法。上法自然之运行。"},{id:"xishuitu",term:"下袭水土",pinyin:"xià xí shuǐ tǔ",meaning:"袭：因。下因水土一定之理。朱注：「皆兼内外该本末而言也。」"},{id:"chizai",term:"持载",pinyin:"chí zài",meaning:"持载万物（地之德）。"},{id:"fudao",term:"覆帱",pinyin:"fù dào",meaning:"帱：读 dào，覆盖。覆盖万物（天之德）。"},{id:"cuoxing",term:"错行",pinyin:"cuò xíng",meaning:"错：犹迭。四时交替运行。"},{id:"daiming",term:"代明",pinyin:"dài míng",meaning:"交替光明。日月更迭照耀。"},{id:"xiaodechuanliu",term:"小德川流",pinyin:"xiǎo dé chuān liú",meaning:"朱注：「小德者，全体之分；川流者，如川之流，脉络分明而往不息也。」"},{id:"dadedunhua",term:"大德敦化",pinyin:"dà dé dūn huà",meaning:"朱注：「大德者，万殊之本；敦化者，敦厚其化，根本盛大而出无穷也。」"}];return(c,n)=>{const l=o("DaoTextReading"),t=o("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第30章",tabindex:"-1"},[a("中庸·第30章 "),i("a",{class:"header-anchor",href:"#中庸·第30章","aria-label":'Permalink to "中庸·第30章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[a("第三十章以四句概括孔子（祖述尧舜、宪章文武、上律天时、下袭水土），再以天地、四时、日月为喻，收在「"),i("strong",null,"万物并育而不相害，道并行而不相悖，小德川流，大德敦化"),a("」。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),e(l,{colophon:"祖述尧舜 · 宪章文武 · 小德川流，大德敦化",tone:"ink",sections:r,glossary:s,"default-mode":"slips","aria-label":"中庸·第30章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(t,{items:[{term:"祖述",pinyin:["zǔ","shù"],meaning:"远宗其道。"},{term:"宪章",pinyin:["xiàn","zhāng"],meaning:"近守其法。一远一近，是承接的两种方式。"},{term:"上律天时",pinyin:["shàng","lǜ","tiān","shí"],meaning:"律：法。上法自然之运行。"},{term:"下袭水土",pinyin:["xià","xí","shuǐ","tǔ"],meaning:"袭：因。下因水土一定之理。朱注：「兼内外该本末而言也。」"},{term:"覆帱",pinyin:["fù","dào"],meaning:"帱：读 dào，覆盖——天之德。"},{term:"持载",pinyin:["chí","zài"],meaning:"持载万物——地之德。"},{term:"错行",pinyin:["cuò","xíng"],meaning:"错：迭。四时交替运行。"},{term:"代明",pinyin:["dài","míng"],meaning:"日月更迭光明。"}]}),e(t,{items:[{term:"万物并育而不相害",pinyin:["wàn","wù","bìng","yù"],meaning:"万物一同生长而不相侵害。"},{term:"道并行而不相悖",pinyin:["dào","bìng","xíng"],meaning:"众道一同运行而不相违背——天地之所以为大，正在此。"},{term:"小德川流",pinyin:["xiǎo","dé","chuān","liú"],meaning:"朱注：「小德者，全体之分；川流者，脉络分明而往不息。」"},{term:"大德敦化",pinyin:["dà","dé","dūn","huà"],meaning:"朱注：「大德者，万殊之本；敦化者，敦厚其化，根本盛大而出无穷。」"}]}),n[4]||(n[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>祖述尧舜 · 上律天时</strong>：仲尼远宗尧舜之道，近守文武之法；上法天时的运行，下因水土的条理。</p><p><strong>辟如天地之无不持载</strong>：譬如天地无不承载、无不覆盖，譬如四时交替运行、日月更迭照耀。</p><p><strong>万物并育而不相害</strong>：万物一同生长而不相侵害，众道一同运行而不相违背——小德如川流般脉络分明而不息，大德敦厚其化而根本盛大、其出不穷。<strong>这就是天地之所以为大。</strong></p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第三十章只有三节，全是赞语：</p><ol><li><strong>孔子四句</strong>：祖述尧舜（远宗其道）、宪章文武（近守其法）、上律天时、下袭水土</li><li><strong>两个比喻</strong>：如天地之持载覆帱、如四时错行日月代明</li><li><strong>四句总赞</strong>：万物并育而不相害，道并行而不相悖，小德川流，大德敦化——「此天地之所以为大也」</li></ol><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>孔子这四句是「集大成」的具体写法</strong>：往上承（尧舜）、往下接（文武）、向上法（天时）、向下因（水土）。<strong>四个方向都到位，才叫大。</strong></li><li><strong>「并育而不相害，并行而不相悖」是全篇最开阔的一句</strong>：万物一起生长而不互相伤害，种种道一起运行而不互相违背。这既是天地之所以为大，也是第 27 章「道并行」与第 8 章「宽柔以教」的极致形态。</li><li><strong>「小德川流，大德敦化」把「多」与「一」配好了</strong>：朱注说「小德者，全体之分；大德者，万殊之本」——<strong>支流脉络分明而不息，根本敦厚而输出无穷</strong>。这两者不是对立的，而是同一件事的两面。</li><li><strong>它接第 29 章的「世为天下道」</strong>：上章说一个人的言行成为天下的道、法、则；本章说这力量从何而来——从<strong>并育并行</strong>而来。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>「并育不相害」</strong>：多元共存不是妥协，是「大」的条件。</li><li><strong>「小德川流，大德敦化」</strong>：既要脉络分明的持续输出，也要有那个敦厚的根本——两头都要。</li><li><strong>四句当自省</strong>：我承接的是谁（祖述）、守的是什么（宪章）、顺着什么时势（律天时）、依据什么实际（袭水土）？</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>仲尼<strong>远宗尧舜之道，近守文武之法；上法天时的运行，下因水土的条理</strong>。</p><p>他像天地一样，无不承载、无不覆盖；像四时交替、日月更迭。</p><p>于是：<strong>万物一同生长而不相害，众道一同运行而不相背</strong>——小德如川流，脉络分明、奔流不息；大德如根本，敦厚其化、其出不穷。<strong>这就是天地之所以为大。</strong></p><p>这一章是全篇最开阔的地方。它说的不是某一条道对，而是<strong>很多道可以一起走</strong>；不是某一种德高，而是<strong>分流的与根本的都在起作用</strong>。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「祖述尧舜，宪章文武」——我承接的是谁？守的是什么？</li><li>「上律天时，下袭水土」——我顺着什么时势？依据什么实际？</li><li>「万物并育而不相害，道并行而不相悖」——我所在的圈子里，容得下「多条道一起走」吗？</li><li>「小德川流，大德敦化」——我更像「川流」还是「敦化」？缺哪一头？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-29">中庸·第29章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-31">中庸·第31章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{y as __pageData,b as default};
